effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec3 u_xlat1;
vec2 u_xlat2;
float u_xlat3;
float u_xlat8;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat0.xy = u_xlat0.xy * _viewport_ratio.xy;
    u_xlat8 = _angle * 0.0174532924;
    u_xlat1.x = sin((-u_xlat8));
    u_xlat2.x = sin(u_xlat8);
    u_xlat3 = cos(u_xlat8);
    u_xlat1.y = u_xlat3;
    u_xlat1.z = u_xlat2.x;
    u_xlat2.y = dot(u_xlat1.zy, u_xlat0.xy);
    u_xlat2.x = dot(u_xlat1.yx, u_xlat0.xy);
    u_xlat0.xy = u_xlat2.xy + vec2(0.5, 0.5);
    u_xlat0.xy = clamp(u_xlat0.xy, 0.0, 1.0);
    u_xlat0 = texture(inputImg, u_xlat0.xy);
    u_xlat0 = u_xlat0 * vs_COLOR0;
    u_xlat0 = u_xlat0 * vec4(vec4(_intensity, _intensity, _intensity, _intensity));
    fragColor = u_xlat0 * _color;
    return;
}
